styles.css:
position: relative;
overflow: hidden;
max-inline-size: 22.5rem;
--ls-card-solutions-accent-colour: var(--wp--custom--color--card--solutions--brand);
--ls-card-solutions-accent-resolved: var(--ls-card-solutions-accent-colour, var(--wp--custom--color--card--solutions--brand));
--ls-card-solutions-border-active: var(--ls-card-solutions-accent-resolved);
--ls-card-solutions-shadow-active: 1px 4px 12px 4px color-mix(in srgb, var(--ls-card-solutions-accent-resolved) 50%, transparent);

& .ls-card-solutions__content {
	display: flex;
	flex: 1 1 auto;
	flex-direction: column;
	gap: var(--wp--preset--spacing--10);
	inline-size: 100%;
}

& .ls-card-solutions__content > * {
	margin-block: 0;
}

& .ls-card-solutions__content .wp-block-heading {
	color: var(--wp--custom--color--text--default);
}

& .ls-card-solutions__cta {
	margin-top: auto;
	margin-bottom: 0;
}

& .ls-card-solutions__cta .wp-block-button {
	margin: 0;
}
